const originalText=new WeakMap(),originalAttributes=new WeakMap();
let currentLanguage='mn';
function readPreference(key,fallback){try{return localStorage.getItem(key)||fallback;}catch{return fallback;}}
function savePreference(key,value){try{localStorage.setItem(key,value);}catch{}}
function translateString(s){if(translations[s]!==undefined)return translations[s];if(/^(Постер|Reel|Chatbot|Brandbook|Профайл, ковер|Boost хийх заавар|Вэб \/ танилцуулга|Аппликейшн) × \d+$/.test(s)){const [n,q]=s.split(' × ');return (translations[n]||n)+' × '+q;}if(s.startsWith('Нийт: '))return s.replace('Нийт: ','Total: ');return s;}
function applyLanguage(){observer.disconnect();const walker=document.createTreeWalker(document.body,NodeFilter.SHOW_TEXT);let n;while(n=walker.nextNode()){if(n.parentElement.closest('script,style,textarea,#language-code'))continue;let source=originalText.get(n);if(source===undefined){source=n.nodeValue;originalText.set(n,source);}const key=source.trim();const target=currentLanguage==='en'?translateString(key):key;n.nodeValue=source.replace(key,target);}document.querySelectorAll('[placeholder]').forEach(el=>{if(!originalAttributes.has(el))originalAttributes.set(el,el.getAttribute('placeholder'));const s=originalAttributes.get(el);el.setAttribute('placeholder',currentLanguage==='en'?translateString(s):s);});document.documentElement.lang=currentLanguage;document.querySelector('#language-code').textContent=currentLanguage==='en'?'EN':'MN';document.querySelector('#language-toggle').setAttribute('aria-label',currentLanguage==='en'?'Монгол хэл рүү шилжих':'Switch to English');document.title=currentLanguage==='en'?'Chameleon — Let your brand show its colors':'Chameleon — Брэндийнхээ өнгийг гарга';updateThemeControl();observer.observe(document.body,{childList:true,subtree:true,characterData:true});}
function updateThemeControl(){const dark=document.documentElement.dataset.theme==='dark';document.querySelector('#theme-toggle').setAttribute('aria-pressed',String(dark));document.querySelector('#theme-toggle').setAttribute('aria-label',currentLanguage==='en'?(dark?'Switch to light mode':'Switch to dark mode'):(dark?'Цайвар горимд шилжих':'Бараан горимд шилжих'));}
function setTheme(theme){document.documentElement.dataset.theme=theme;savePreference('chameleon-theme',theme);updateThemeControl();}
document.querySelector('#theme-toggle').addEventListener('click',()=>setTheme(document.documentElement.dataset.theme==='dark'?'light':'dark'));
document.querySelector('#language-toggle').addEventListener('click',()=>{currentLanguage=currentLanguage==='mn'?'en':'mn';savePreference('chameleon-language',currentLanguage);applyLanguage();});
// Preserve option values when visible labels are translated.
document.querySelectorAll('select option').forEach(o=>o.value=o.textContent);
document.querySelector('.process').id='process';document.querySelectorAll('.services-grid article')[2].id='technology';
document.querySelectorAll('#nav a').forEach(a=>a.addEventListener('click',()=>{document.querySelectorAll('#nav a').forEach(l=>l.removeAttribute('aria-current'));a.setAttribute('aria-current','location');}));
const observer=new MutationObserver(records=>{observer.disconnect();for(const r of records)if(r.type==='characterData')originalText.delete(r.target);applyLanguage();observer.observe(document.body,{childList:true,subtree:true,characterData:true});});
currentLanguage=readPreference('chameleon-language','mn');if(!['en','mn'].includes(currentLanguage))currentLanguage='mn';setTheme(readPreference('chameleon-theme','light'));applyLanguage();observer.observe(document.body,{childList:true,subtree:true,characterData:true});
